//! Finite groups and their Cayley graphs (edges g ~ g s, right multiplication):
//! - SL_m(F_{2^k}), m = 2, 3, with elementary generators e_ab(1), e_ab(x) (the notes' §5 families,
//!   F_{2^k} = F_2[x]/(p)) or with random generators (plus inverses);
//! - PGL_2(F_q) / PSL_2(F_q), q an odd prime, with the LPS generators of X^{p,q} (p ≡ 1 mod 4 prime):
//!   the Cayley graph of the group generated by the p+1 matrices [[a+bi, c+di], [-c+di, a-bi]],
//!   a^2+b^2+c^2+d^2 = p, a > 0 odd, b, c, d even, i^2 = -1 mod q.
//! Structured placements: g -> gW (subspace) and g -> M_g P M_g^{-1} (matrix, when m*k <= 8).

use super::f2;
use super::graph::Graph;
use rand::{rngs::SmallRng, Rng, SeedableRng};
use std::collections::HashMap;

/// Default irreducible polynomials (bit i = coefficient of x^i).
pub fn default_modulus(k: usize) -> u32 {
    match k {
        1 => 0b11,
        2 => 0b111,
        3 => 0b1011,
        4 => 0b10011,
        5 => 0b100101,
        6 => 0b1000011,
        7 => 0b10000011,
        8 => 0b100011011,
        _ => panic!("k <= 8"),
    }
}

/// Irreducibility test by trial division (small degrees).
pub fn is_irreducible(p: u32) -> bool {
    let deg = 31 - p.leading_zeros();
    if deg == 0 {
        return false;
    }
    let pmod = |mut a: u32, b: u32| {
        let db = 31 - b.leading_zeros();
        while a != 0 && 31 - a.leading_zeros() >= db {
            a ^= b << (31 - a.leading_zeros() - db);
        }
        a
    };
    for q in 2..(1u32 << (deg / 2 + 1)) {
        let dq = 31 - q.leading_zeros();
        if dq >= 1 && dq <= deg / 2 && pmod(p, q) == 0 {
            return false;
        }
    }
    true
}

#[derive(Clone)]
pub struct Gf2k {
    pub k: usize,
    pub q: usize,
    pub modulus: u32,
    pub mul: Vec<u8>,
    pub inv: Vec<u8>,
}

impl Gf2k {
    pub fn new(k: usize, modulus: u32) -> Gf2k {
        assert!(k >= 1 && k <= 8 && is_irreducible(modulus) && 31 - modulus.leading_zeros() == k as u32);
        let q = 1usize << k;
        let mut mul = vec![0u8; q * q];
        for a in 0..q {
            for b in 0..q {
                let (mut x, mut y, mut r) = (a as u32, b as u32, 0u32);
                while y != 0 {
                    if y & 1 == 1 {
                        r ^= x;
                    }
                    y >>= 1;
                    x <<= 1;
                    if x & (q as u32) != 0 {
                        x ^= modulus;
                    }
                }
                mul[a * q + b] = r as u8;
            }
        }
        let mut inv = vec![0u8; q];
        for a in 1..q {
            inv[a] = (1..q).find(|&b| mul[a * q + b] == 1).unwrap() as u8;
        }
        Gf2k { k, q, modulus, mul, inv }
    }
    #[inline]
    pub fn m(&self, a: u8, b: u8) -> u8 {
        self.mul[(a as usize) * self.q + b as usize]
    }
}

/// m x m matrices over F_{2^k}, row-major, entries < q, m <= 3.
pub type Mat = [u8; 9];

pub struct SlGroup {
    pub field: Gf2k,
    pub m: usize,
    pub gens: Vec<Mat>,
    pub elems: Vec<Mat>,
    pub graph: Graph,
}

pub fn mat_mul(f: &Gf2k, m: usize, a: &Mat, b: &Mat) -> Mat {
    let mut c = [0u8; 9];
    for i in 0..m {
        for j in 0..m {
            let mut s = 0u8;
            for l in 0..m {
                s ^= f.m(a[i * m + l], b[l * m + j]);
            }
            c[i * m + j] = s;
        }
    }
    c
}

pub fn mat_identity(m: usize) -> Mat {
    let mut a = [0u8; 9];
    for i in 0..m {
        a[i * m + i] = 1;
    }
    a
}

pub fn det(f: &Gf2k, m: usize, a: &Mat) -> u8 {
    match m {
        1 => a[0],
        2 => f.m(a[0], a[3]) ^ f.m(a[1], a[2]),
        3 => {
            let t = |i: usize, j: usize, l: usize| f.m(a[i], f.m(a[j], a[l]));
            t(0, 4, 8) ^ t(0, 5, 7) ^ t(1, 3, 8) ^ t(1, 5, 6) ^ t(2, 3, 7) ^ t(2, 4, 6)
        }
        _ => unreachable!(),
    }
}

pub fn mat_inverse(f: &Gf2k, m: usize, a: &Mat) -> Option<Mat> {
    let mut x = *a;
    let mut y = mat_identity(m);
    for c in 0..m {
        let p = (c..m).find(|&r| x[r * m + c] != 0)?;
        for j in 0..m {
            x.swap(c * m + j, p * m + j);
            y.swap(c * m + j, p * m + j);
        }
        let iv = f.inv[x[c * m + c] as usize];
        for j in 0..m {
            x[c * m + j] = f.m(x[c * m + j], iv);
            y[c * m + j] = f.m(y[c * m + j], iv);
        }
        for r in 0..m {
            if r != c && x[r * m + c] != 0 {
                let t = x[r * m + c];
                for j in 0..m {
                    x[r * m + j] ^= f.m(t, x[c * m + j]);
                    y[r * m + j] ^= f.m(t, y[c * m + j]);
                }
            }
        }
    }
    Some(y)
}

fn code(k: usize, m: usize, a: &Mat) -> u64 {
    (0..m * m).fold(0u64, |c, i| c | ((a[i] as u64) << (k * i)))
}

/// Elementary generators e_ab(1), e_ab(x) for a != b (x = the field element 2).
pub fn elementary_gens(m: usize, with_x: bool) -> Vec<Mat> {
    let mut g = vec![];
    for a in 0..m {
        for b in 0..m {
            if a != b {
                let mut e = mat_identity(m);
                e[a * m + b] = 1;
                g.push(e);
                if with_x {
                    let mut e = mat_identity(m);
                    e[a * m + b] = 2;
                    g.push(e);
                }
            }
        }
    }
    g
}

/// `count` random elements of SL_m together with their inverses (involutions counted once).
pub fn random_gens(f: &Gf2k, m: usize, count: usize, seed: u64) -> Vec<Mat> {
    let mut rng = SmallRng::seed_from_u64(seed);
    let mut out = vec![];
    while out.len() < count {
        let mut a = [0u8; 9];
        for i in 0..m * m {
            a[i] = rng.gen_range(0..f.q) as u8;
        }
        let dt = det(f, m, &a);
        if dt == 0 {
            continue;
        }
        let iv = f.inv[dt as usize];
        for j in 0..m {
            a[j] = f.m(a[j], iv);
        }
        if a == mat_identity(m) {
            continue;
        }
        out.push(a);
    }
    let mut all = out.clone();
    for a in &out {
        let b = mat_inverse(f, m, a).unwrap();
        if b != *a {
            all.push(b);
        }
    }
    all
}

/// Cayley graph of the subgroup of GL_m(F_{2^k}) generated by `gens` (closed under inverses),
/// edges g ~ g s. Vertex 0 is the identity.
pub fn sl_cayley(field: Gf2k, m: usize, gens: Vec<Mat>, name: &str) -> SlGroup {
    let k = field.k;
    let bits = k * m * m;
    let d = gens.len();
    let id = mat_identity(m);
    let mut elems: Vec<Mat> = vec![id];
    let mut adj: Vec<u32> = vec![];
    // index: dense table for <= 28 bits, else hash map
    let mut table: Vec<u32> = if bits <= 28 { vec![u32::MAX; 1usize << bits] } else { vec![] };
    let mut hmap: HashMap<u64, u32> = HashMap::new();
    let mut lookup_insert = |c: u64, next: u32, table: &mut Vec<u32>| -> (u32, bool) {
        if bits <= 28 {
            let e = &mut table[c as usize];
            if *e == u32::MAX {
                *e = next;
                (next, true)
            } else {
                (*e, false)
            }
        } else {
            match hmap.get(&c) {
                Some(&i) => (i, false),
                None => {
                    hmap.insert(c, next);
                    (next, true)
                }
            }
        }
    };
    lookup_insert(code(k, m, &id), 0, &mut table);
    let mut head = 0usize;
    while head < elems.len() {
        let g = elems[head];
        for s in &gens {
            let h = mat_mul(&field, m, &g, s);
            let (i, new) = lookup_insert(code(k, m, &h), elems.len() as u32, &mut table);
            if new {
                elems.push(h);
            }
            adj.push(i);
        }
        head += 1;
    }
    let n = elems.len();
    let graph = Graph { n, d, adj, name: name.to_string() };
    SlGroup { field, m, gens, elems, graph }
}

/// SL_m(F_2[x]/(p)) with the 2m(m-1) elementary generators e_ab(1), e_ab(x).
pub fn sl_elementary(m: usize, k: usize, modulus: u32) -> SlGroup {
    let f = Gf2k::new(k, modulus);
    let gens = elementary_gens(m, k > 1);
    sl_cayley(f, m, gens, &format!("SL{m}(F{})_p{:b}", 1 << k, modulus))
}

impl SlGroup {
    pub fn n(&self) -> usize {
        self.elems.len()
    }
    /// Vector of F_q^m as bits: coordinate a occupies bits k*a .. k*a+k.
    pub fn apply(&self, g: &Mat, v: u64) -> u64 {
        let (k, m) = (self.field.k, self.m);
        let mask = (1u64 << k) - 1;
        let mut out = 0u64;
        for b in 0..m {
            let mut s = 0u8;
            for a in 0..m {
                s ^= self.field.m(g[b * m + a], ((v >> (k * a)) & mask) as u8);
            }
            out |= (s as u64) << (k * b);
        }
        out
    }
    /// Basis of W = U^m, U = span(1, x, ..., x^{j-1}).
    pub fn w_basis(&self, j: usize) -> Vec<u64> {
        let k = self.field.k;
        (0..self.m).flat_map(|a| (0..j).map(move |t| 1u64 << (k * a + t))).collect()
    }
    /// d_J(gW, W) = dim(gW + W) - dim W.
    pub fn d_j(&self, g: &Mat, w: &[u64]) -> u32 {
        let mut vs: Vec<u64> = w.to_vec();
        vs.extend(w.iter().map(|&x| self.apply(g, x)));
        f2::rank_vectors(&vs) - w.len() as u32
    }
    /// F_2-matrix (byte rows) of g acting on F_2^{mk}, mk <= 8.
    pub fn f2_matrix(&self, g: &Mat) -> u64 {
        let mk = self.m * self.field.k;
        assert!(mk <= 8);
        let mut a = 0u64;
        for j in 0..mk {
            let col = self.apply(g, 1u64 << j);
            for i in 0..mk {
                if (col >> i) & 1 == 1 {
                    a |= f2::unit(i, j);
                }
            }
        }
        a
    }
    /// Matrix placement f(g) = M_g P M_g^{-1}, P = projection onto U^m along span(x^t : t >= j)^m.
    pub fn conj_projection_placement(&self, j: usize) -> (usize, Vec<u64>) {
        let (k, m) = (self.field.k, self.m);
        let mu = m * k;
        let mut p = 0u64;
        for a in 0..m {
            for t in 0..j {
                p |= f2::unit(a * k + t, a * k + t);
            }
        }
        let f = self
            .elems
            .iter()
            .map(|g| {
                let mg = self.f2_matrix(g);
                f2::mul(f2::mul(mg, p), f2::inverse(mg, mu).unwrap())
            })
            .collect();
        (mu, f)
    }
}

/// PGL_2(F_q) elements, normalised projectively.
pub struct Pgl2 {
    pub q: u64,
    pub elems: Vec<[u64; 4]>,
    pub graph: Graph,
}

fn powmod(mut b: u64, mut e: u64, m: u64) -> u64 {
    let mut r = 1 % m;
    b %= m;
    while e > 0 {
        if e & 1 == 1 {
            r = r * b % m;
        }
        b = b * b % m;
        e >>= 1;
    }
    r
}

fn normalise(a: [u64; 4], q: u64) -> [u64; 4] {
    let s = if a[0] != 0 { a[0] } else { a[1] };
    let iv = powmod(s, q - 2, q);
    [a[0] * iv % q, a[1] * iv % q, a[2] * iv % q, a[3] * iv % q]
}

pub fn lps_generators(p: u64, q: u64) -> Vec<[u64; 4]> {
    assert!(p % 4 == 1 && q % 4 == 1 && p != q);
    let i = (1..q).find(|&x| x * x % q == q - 1).unwrap();
    let r = (p as f64).sqrt() as i64 + 1;
    let mut gens = vec![];
    for a in 1..=r {
        if a % 2 == 0 {
            continue;
        }
        for b in -r..=r {
            for c in -r..=r {
                for d in -r..=r {
                    if b % 2 != 0 || c % 2 != 0 || d % 2 != 0 {
                        continue;
                    }
                    if (a * a + b * b + c * c + d * d) as u64 != p {
                        continue;
                    }
                    let md = |x: i64| x.rem_euclid(q as i64) as u64;
                    let iq = i as i64;
                    let m = [md(a + b * iq), md(c + d * iq), md(-c + d * iq), md(a - b * iq)];
                    gens.push(normalise(m, q));
                }
            }
        }
    }
    assert_eq!(gens.len() as u64, p + 1);
    gens
}

/// Cayley graph of the subgroup of PGL_2(F_q) generated by `gens` (q prime).
pub fn pgl2_cayley(q: u64, gens: &[[u64; 4]], name: &str) -> Pgl2 {
    let enc = |a: &[u64; 4]| (((a[0] * q + a[1]) * q + a[2]) * q + a[3]) as usize;
    let mut table = vec![u32::MAX; (q * q * q * q) as usize];
    let id = [1, 0, 0, 1];
    let mut elems = vec![id];
    table[enc(&id)] = 0;
    let mut adj = vec![];
    let mut head = 0;
    while head < elems.len() {
        let g = elems[head];
        for s in gens {
            let h = normalise(
                [
                    (g[0] * s[0] + g[1] * s[2]) % q,
                    (g[0] * s[1] + g[1] * s[3]) % q,
                    (g[2] * s[0] + g[3] * s[2]) % q,
                    (g[2] * s[1] + g[3] * s[3]) % q,
                ],
                q,
            );
            let c = enc(&h);
            if table[c] == u32::MAX {
                table[c] = elems.len() as u32;
                elems.push(h);
            }
            adj.push(table[c]);
        }
        head += 1;
    }
    let n = elems.len();
    Pgl2 { q, elems, graph: Graph { n, d: gens.len(), adj, name: name.to_string() } }
}

pub fn lps(p: u64, q: u64) -> Pgl2 {
    pgl2_cayley(q, &lps_generators(p, q), &format!("LPS_X{p}_{q}"))
}

/// PSL_2(F_q) (q odd prime) with random generators plus inverses.
pub fn psl2_random(q: u64, count: usize, seed: u64) -> Pgl2 {
    let mut rng = SmallRng::seed_from_u64(seed);
    let mut gens = vec![];
    while gens.len() < count {
        let a = [rng.gen_range(0..q), rng.gen_range(0..q), rng.gen_range(0..q), rng.gen_range(0..q)];
        let det = (a[0] * a[3] % q + q * q - a[1] * a[2] % q) % q;
        if det != 1 {
            continue;
        }
        gens.push(normalise(a, q));
    }
    let mut all = gens.clone();
    for a in &gens {
        let inv = normalise([a[3], q - a[1] % q, q - a[2] % q, a[0]], q);
        let inv = [inv[0] % q, inv[1] % q, inv[2] % q, inv[3] % q];
        if inv != *a {
            all.push(inv);
        }
    }
    pgl2_cayley(q, &all, &format!("PSL2({q})_rand{count}_s{seed}"))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn sl_orders() {
        let g = sl_elementary(2, 3, default_modulus(3));
        assert_eq!(g.n(), 504);
        assert!(g.graph.is_symmetric());
        let g = sl_elementary(2, 4, default_modulus(4));
        assert_eq!(g.n(), 4080);
        let g = sl_elementary(3, 2, default_modulus(2));
        assert_eq!(g.n(), 60480);
        assert!(g.graph.is_symmetric());
        let f = Gf2k::new(1, 0b11);
        let gens = random_gens(&f, 3, 2, 5);
        let g = sl_cayley(f, 3, gens, "SL3(F2)r");
        assert!(g.graph.is_symmetric());
    }
    #[test]
    fn sl2_dj_matches_notes() {
        // notes §5.2 table: k = 3: E_pairs d_J = 1.869, k = 4: 3.313, edges 0.5
        for (k, ep) in [(3usize, 1.869f64), (4, 3.313)] {
            let g = sl_elementary(2, k, default_modulus(k));
            let w = g.w_basis(k / 2);
            let e: f64 = g.gens.iter().map(|s| g.d_j(s, &w) as f64).sum::<f64>() / g.gens.len() as f64;
            let p: f64 = g.elems.iter().map(|x| g.d_j(x, &w) as f64).sum::<f64>() / g.n() as f64;
            assert!((e - 0.5).abs() < 1e-12);
            assert!((p - ep).abs() < 1e-3, "{k} {p}");
        }
    }
    #[test]
    fn lps_sizes() {
        let x = lps(5, 13);
        assert_eq!(x.graph.n, 2184);
        assert!(x.graph.is_symmetric() && x.graph.is_simple());
        let x = lps(5, 29);
        assert_eq!(x.graph.n, 12180);
    }
}
